new file mode 100644
index 0000000..6d48180
--- /dev/null
+++ b/backend/src/GithubApi/__tests__/parseIssueUrl.test.ts
@@ -0,0 +1,51 @@
+import { expect, test } from 'vitest'
+import { GithubApi, InvalidIssueUrlError } from '../index.js'
+
+const gh = new GithubApi()
+
+test('accepts standard github issue URL', () => {
+  const p = gh.parseIssueUrl('https://github.com/o/r/issues/12')
+  expect(p).toEqual({ host: 'github.com', owner: 'o', repo: 'r', issueNumber: 12 })
+})
+
+test('accepts trailing slash and query/fragment', () => {
+  const p = gh.parseIssueUrl('https://github.com/o/r/issues/34/?a=1#x')
+  expect(p.issueNumber).toBe(34)
+})
+
+test('accepts www.github.com', () => {
+  const p = gh.parseIssueUrl('https://www.github.com/o/r/issues/5')
+  expect(p.host).toBe('github.com')
+})
+
+test('accepts enterprise host from GITHUB_HOSTS', () => {
+  process.env.GITHUB_HOSTS = 'github.com,gh.example.com'
+  const p = gh.parseIssueUrl('https://gh.example.com/o/r/issues/7')
+  expect(p.host).toBe('gh.example.com')
+})
+
+// Rejected cases
+test('rejects http scheme', () => {
+  expect(() => gh.parseIssueUrl('http://github.com/o/r/issues/1')).toThrow(InvalidIssueUrlError)
+})
+
+test('rejects pull url', () => {
+  expect(() => gh.parseIssueUrl('https://github.com/o/r/pull/2')).toThrow(InvalidIssueUrlError)
+})
+
+test('rejects non-numeric issue number', () => {
+  expect(() => gh.parseIssueUrl('https://github.com/o/r/issues/abc')).toThrow(InvalidIssueUrlError)
+})
+
+test('rejects zero issue number', () => {
+  expect(() => gh.parseIssueUrl('https://github.com/o/r/issues/0')).toThrow(InvalidIssueUrlError)
+})
+
+test('rejects unknown host', () => {
+  process.env.GITHUB_HOSTS = 'github.com'
+  expect(() => gh.parseIssueUrl('https://other.example.com/o/r/issues/1')).toThrow(InvalidIssueUrlError)
+})
+
+test('rejects invalid owner/repo names', () => {
+  expect(() => gh.parseIssueUrl('https://github.com/owner$/repo/issues/1')).toThrow(InvalidIssueUrlError)
+})
