@@ -8,28 +10,67 @@ export class GithubApi{
     public readonly token: string | undefined
     constructor(token?: string){
         this.token = token ?? process.env.GITHUB_TOKEN
+        // Octokit should use enterprise baseUrl when host is not github.com.
+        // We'll lazily construct octokit per host when needed; default to github.com
         this.octokit = new Octokit({auth:this.token})
     }

+    private octokitForHost(host: string) {
+        if (host === 'github.com') return this.octokit
+        const baseUrl = `https://${host}/api/v3`
+        return new Octokit({ auth: this.token, baseUrl })
+    }
+
+    /**
+     * Parse and validate a GitHub issue URL.
+     * Returns { host, owner, repo, issueNumber } or throws InvalidIssueUrlError.
+     */
     parseIssueUrl(issueUrl:string){
-        const parts = issueUrl.replace("https://github.com/","").split("/")
-        return {
-            owner:parts[0] ?? "",
-            repo:parts[1] ?? "",
-            issueNumber:parseInt(parts[3] ?? "0")
+        try {
+            const url = new URL(issueUrl)
+            if (url.protocol !== "https:") throw new InvalidIssueUrlError("Only https:// URLs are allowed")
+            // Accept www.github.com as github.com
+            const host = (url.hostname === "www.github.com") ? "github.com" : url.hostname
+
+            const envHosts = (process.env.GITHUB_HOSTS ?? "github.com").split(",").map(h=>h.trim()).filter(Boolean)
+            if (!envHosts.includes(host)) throw new InvalidIssueUrlError(`Unknown host: ${host}`)
+
+            // path like /owner/repo/issues/123 with optional trailing slash, query, fragment
+            const parts = url.pathname.replace(/(^\/|\/$)/g, "").split('/')
+            const [owner = "", repo = "", maybeIssues = "", maybeNumber = ""] = parts
+
+            if (maybeIssues !== "issues") throw new InvalidIssueUrlError("URL is not an issue URL")
+            if (/^pulls?$/.test(maybeIssues)) throw new InvalidIssueUrlError("Pull request URLs are not accepted")
+
+            // owner and repo validation per GitHub: allow alphanum, -,_ and .
+            const validName = /^[A-Za-z0-9_.-]+$/
+            if (!owner || !validName.test(owner)) throw new InvalidIssueUrlError("Invalid owner name")
+            if (!repo || !validName.test(repo)) throw new InvalidIssueUrlError("Invalid repo name")
+
+            const issueNumber = Number(maybeNumber ?? 0)
+            if (!Number.isInteger(issueNumber) || issueNumber <= 0) throw new InvalidIssueUrlError("Invalid issue number")
+
+            return { host, owner, repo, issueNumber }
+        } catch (err) {
+            if (err instanceof InvalidIssueUrlError) throw err
+            throw new InvalidIssueUrlError("Invalid issue URL")
         }
     }

     async getDefaultBranch(issueUrl: string): Promise<string> {
-        const { owner, repo } = this.parseIssueUrl(issueUrl)
-        const { data } = await this.octokit.rest.repos.get({ owner, repo })
+        const { owner, repo, host } = this.parseIssueUrl(issueUrl)
+        const oct = this.octokitForHost(host)
+        const { data } = await oct.rest.repos.get({ owner, repo })
         return data.default_branch
     }

+
+
     async getIssue(issueUrl:string){
         try {
-            const {owner,repo,issueNumber} = this.parseIssueUrl(issueUrl)
-            const {data} = await this.octokit.rest.issues.get({
+            const {owner,repo,issueNumber,host} = this.parseIssueUrl(issueUrl)
+            const oct = this.octokitForHost(host)
+            const {data} = await oct.rest.issues.get({
                 owner,repo,issue_number:issueNumber
             })
             logger.info("Issue: "+data.title)
@@ -42,11 +83,12 @@ export class GithubApi{

